package com.gielinordeeds;

import net.runelite.api.coords.WorldPoint;
import org.junit.BeforeClass;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * The outpost rule, pinned against the real survey rather than a toy grid.
 *
 * It exists because the frontier rule assumed Gielinor was one walkable
 * continent. It is not: Corsair Cove is reached by ship, so nothing there ever
 * touches land a mainland estate owns, and a run that sailed out to do The
 * Corsair Curse arrived somewhere with no legal move in it. These tests use the
 * actual places that broke it, because the numbers are the argument -- a
 * regression that quietly re-strands Corsair Cove would pass any test written
 * against invented coordinates.
 */
public class OutpostTest
{
	private static ParcelGrid grid;

	/** Where the run that hit this was standing. */
	private static final WorldPoint CORSAIR_COVE = new WorldPoint(2571, 2857, 0);
	private static final WorldPoint LUMBRIDGE = new WorldPoint(3222, 3218, 0);
	/** The far shore of the Karamja ferry, 6 deeds off Rimmington. */
	private static final WorldPoint MUSA_POINT = new WorldPoint(2916, 3162, 0);
	private static final WorldPoint RIMMINGTON = new WorldPoint(2957, 3214, 0);
	private static final WorldPoint PORT_KHAZARD = new WorldPoint(2662, 3153, 0);
	/** Karamja's western tip, 7 deeds across the strait from Port Khazard. */
	private static final WorldPoint KARAMJA_WEST = new WorldPoint(2688, 3208, 0);
	private static final WorldPoint KOUREND = new WorldPoint(1611, 3672, 0);
	/** Where the ship ties up at Corsair Cove -- a water deed, like every dock. */
	private static final WorldPoint CORSAIR_COVE_SHIP = new WorldPoint(2578, 2839, 0);
	/** And where you actually stand when you get off it: a storey above. */
	private static final WorldPoint CORSAIR_COVE_SHIP_DECK =
		new WorldPoint(2578, 2839, 1);

	@BeforeClass
	public static void load() throws Exception
	{
		grid = ParcelGrid.load();
		assertNotNull("parcels.bin should be packaged with the plugin", grid);
	}

	private static Parcel at(WorldPoint wp)
	{
		Parcel p = grid.at(wp);
		assertNotNull("expected a parcel at " + wp, p);
		return p;
	}

	/** An estate holding one deed, the way a run holds its opening grant. */
	private static Estate holding(WorldPoint wp)
	{
		Estate e = new Estate();
		Parcel p = at(wp);
		e.markSurveyed(grid.indexOf(p));
		e.getOwned().put(p.getPid(), 1);
		return e;
	}

	/**
	 * The bug, stated as a test: a Lumbridge estate can found at Corsair Cove.
	 *
	 * Before the rule existed this deed had no legal move at all. Opening it
	 * from the frontier meant 48 water deeds across open sea or 109 round the
	 * coast, which is not a challenge, it is a dead end.
	 */
	@Test
	public void corsairCoveCanBeFoundedFromAMainlandEstate()
	{
		Estate e = holding(LUMBRIDGE);
		Parcel cove = at(CORSAIR_COVE);

		assertFalse("the cove touches nothing a Lumbridge estate owns",
			DeedLock.onFrontier(grid, e, cove));
		assertEquals(DeedLock.Outpost.ALLOWED,
			DeedLock.outpostStatus(grid, e, cove));
	}

	/**
	 * A short hop stays a purchase, not a flag.
	 *
	 * Musa Point is six deeds off Rimmington -- the Karamja ferry, and exactly
	 * the crossing the water tier was built for. If an outpost could be founded
	 * there, buying water would never be worth doing and the money half of the
	 * expansion loop would stop mattering.
	 */
	@Test
	public void aShortCrossingIsTooCloseToFoundOn()
	{
		Estate e = holding(RIMMINGTON);
		assertEquals(6, DeedLock.deedsToEstate(grid, e, at(MUSA_POINT)));
		assertEquals(DeedLock.Outpost.TOO_CLOSE,
			DeedLock.outpostStatus(grid, e, at(MUSA_POINT)));
	}

	/**
	 * The frontier is asked first, so nothing is ever sold at five charges
	 * when it can be had for one.
	 */
	@Test
	public void aNeighbourIsAFrontierSurveyNotAnOutpost()
	{
		Estate e = holding(LUMBRIDGE);
		Parcel here = at(LUMBRIDGE);
		Parcel neighbour = grid.at(here.getPx() + 1, here.getPy());
		assertTrue(DeedLock.onFrontier(grid, e, neighbour));
		assertEquals(DeedLock.Outpost.ON_FRONTIER,
			DeedLock.outpostStatus(grid, e, neighbour));
	}

	/**
	 * An outpost cannot be planted at sea.
	 *
	 * Water pays no rent, so a water outpost could only ever be a way of
	 * hopping the frontier without paying for the ground under it.
	 */
	@Test
	public void openWaterTakesNoOutpost()
	{
		Estate e = holding(LUMBRIDGE);
		Parcel sea = null;
		// Deep water well south-west of Port Sarim, on the way to the cove.
		for (int x = 2700; x < 3000 && sea == null; x += 8)
		{
			Parcel q = grid.at(new WorldPoint(x, 2900, 0));
			if (q != null && !q.isLand())
			{
				sea = q;
			}
		}
		assertNotNull("expected open water south-west of Asgarnia", sea);
		assertEquals(DeedLock.Outpost.NOT_LAND,
			DeedLock.outpostStatus(grid, e, sea));
	}

	/** Ground already surveyed is not founded on again. */
	@Test
	public void knownGroundIsNotAnOutpost()
	{
		Estate e = holding(LUMBRIDGE);
		Parcel cove = at(CORSAIR_COVE);
		e.markSurveyed(grid.indexOf(cove));
		assertEquals(DeedLock.Outpost.KNOWN,
			DeedLock.outpostStatus(grid, e, cove));
	}

	/** Owning nothing means there is nothing to be far from. */
	@Test
	public void anEstateWithNoLandFoundsNothing()
	{
		assertEquals(DeedLock.Outpost.NO_ESTATE,
			DeedLock.outpostStatus(grid, new Estate(), at(CORSAIR_COVE)));
	}

	/**
	 * Distance counts in the steps the frontier walks in.
	 *
	 * Chebyshev, so a diagonal neighbour is one deed away -- the same way it is
	 * one survey away. Measuring it any other way would put the threshold in
	 * different places along the compass than along the diagonals.
	 */
	@Test
	public void distanceIsMeasuredTheWayTheFrontierMoves()
	{
		Estate e = holding(LUMBRIDGE);
		Parcel here = at(LUMBRIDGE);
		assertEquals(0, DeedLock.deedsToEstate(grid, e, here));
		assertEquals(1, DeedLock.deedsToEstate(grid, e,
			grid.at(here.getPx() + 1, here.getPy() + 1)));
		assertEquals(9, DeedLock.deedsToEstate(grid, e,
			grid.at(here.getPx() + 9, here.getPy() - 4)));
		assertEquals(Integer.MAX_VALUE,
			DeedLock.deedsToEstate(grid, new Estate(), here));
	}

	/**
	 * The threshold is exact, because a player will stand on both sides of it.
	 *
	 * One deed short is TOO_CLOSE and the hint tells them to walk further; one
	 * deed over is ALLOWED. An off-by-one here reads as the rule being random.
	 */
	@Test
	public void theThresholdIsWhereItSays()
	{
		Estate e = holding(LUMBRIDGE);
		Parcel here = at(LUMBRIDGE);
		int min = DeedLock.OUTPOST_MIN_DEEDS;

		Parcel just = land(here.getPx() + min - 1, here.getPy());
		Parcel over = land(here.getPx() + min, here.getPy());
		assertEquals(DeedLock.Outpost.TOO_CLOSE,
			DeedLock.outpostStatus(grid, e, just));
		assertEquals(DeedLock.Outpost.ALLOWED,
			DeedLock.outpostStatus(grid, e, over));
	}

	/**
	 * Dry land at this column, searching north for it.
	 *
	 * The threshold test is about distance, so it must not accidentally land on
	 * the Lumbridge swamp's water and fail as NOT_LAND for the wrong reason.
	 */
	private static Parcel land(int px, int py)
	{
		for (int dy = 0; dy < 6; dy++)
		{
			Parcel p = grid.at(px, py - dy);
			if (p != null && p.isLand())
			{
				return p;
			}
		}
		throw new AssertionError("no dry land near " + px + "," + py);
	}

	// ── standing on a storey ─────────────────────────────────────────────

	/**
	 * You do not arrive at Corsair Cove standing on Corsair Cove.
	 *
	 * You arrive on a ship's deck, which is a storey above a water deed,
	 * because every dock in the game is built out over the sea. So the answer
	 * here is "walk ashore", and the panel has to say so rather than leaving a
	 * dead button.
	 */
	@Test
	public void aShipIsMooredOverWaterAndTakesNoOutpost()
	{
		Parcel below = DeedLock.deedUnder(grid, CORSAIR_COVE_SHIP_DECK);
		assertNotNull("a deck belongs to the deed under it", below);
		assertFalse("every dock is a water deed", below.isLand());
		assertEquals(DeedLock.Outpost.NOT_LAND,
			DeedLock.outpostStatus(grid, holding(LUMBRIDGE), below));
	}

	/**
	 * Nearest is not reachable, which is why no shore is guessed at any more.
	 *
	 * From the Corsair Cove mooring the deed at the head of the pier is three
	 * deeds north; a scrap of shore across open water is two north-west and
	 * wins on distance. A run that founded on the near one spent five charges
	 * on ground it could not walk to. Pinned so nobody reintroduces the guess
	 * without meeting the case that killed it.
	 */
	@Test
	public void theNearestShoreIsNotTheReachableOne()
	{
		Parcel ship = grid.at(CORSAIR_COVE_SHIP);
		Parcel acrossWater = grid.at(208, 180);
		Parcel headOfPier = grid.at(210, 178);
		assertNotNull(ship);
		assertTrue("the scrap across the water is land", acrossWater.isLand());
		assertTrue("so is the head of the pier", headOfPier.isLand());

		int near = squared(ship, acrossWater);
		int reachable = squared(ship, headOfPier);
		assertTrue("the unreachable shore is the nearer one, which is the whole "
			+ "problem: " + near + " against " + reachable, near < reachable);
	}

	private static int squared(Parcel a, Parcel b)
	{
		int dx = a.getPx() - b.getPx();
		int dy = a.getPy() - b.getPy();
		return dx * dx + dy * dy;
	}

	/** On dry ground the deed is simply the one under your feet. */
	@Test
	public void onLandTheDeedIsUnderfoot()
	{
		assertEquals(at(LUMBRIDGE).getPid(),
			DeedLock.deedUnder(grid, LUMBRIDGE).getPid());
	}

	/**
	 * A storey belongs to the deed beneath it.
	 *
	 * The same rule the veil and the trespass warning already follow, so all
	 * three agree about the first floor of a building -- and it is what lets an
	 * outpost be founded from an upper floor over dry land.
	 */
	@Test
	public void aStoreyBelongsToTheGroundUnderIt()
	{
		WorldPoint upstairs = new WorldPoint(3222, 3218, 2);
		assertEquals(at(LUMBRIDGE).getPid(),
			DeedLock.deedUnder(grid, upstairs).getPid());
	}

	/** Off the surveyed world entirely -- a cave, an instance -- there is no deed. */
	@Test
	public void groundTheSurveyNeverCoveredHasNoDeed()
	{
		assertNull(DeedLock.deedUnder(grid, new WorldPoint(0, 0, 0)));
		assertNull(DeedLock.deedUnder(grid, null));
		assertNull(DeedLock.deedUnder(null, LUMBRIDGE));
	}

	/** All or nothing: five charges leave, or none do. */
	@Test
	public void anOutpostIsPaidForInFull()
	{
		SurveyCharges c = new SurveyCharges();
		c.grant(DeedLock.OUTPOST_CHARGES - 1);
		assertFalse(c.spend(DeedLock.OUTPOST_CHARGES));
		assertEquals(DeedLock.OUTPOST_CHARGES - 1, c.getCharges());

		c.grant(1);
		assertTrue(c.spend(DeedLock.OUTPOST_CHARGES));
		assertEquals(0, c.getCharges());
	}

	/**
	 * Every ocean crossing in the game is over the threshold and every river
	 * one is under it.
	 *
	 * This is the number the whole rule turns on, so it is checked against the
	 * shipped survey rather than asserted in a comment. If regenerating
	 * parcels.bin moves a coastline far enough to put Kourend inside the
	 * threshold, a run that sails to Zeah is stranded again and this fails.
	 */
	@Test
	public void theThresholdSitsBetweenRiversAndOceans()
	{
		// Kourend is 201 deeds from Lumbridge and 31 from the nearest mainland
		// coast: an ocean by any measure, and an outpost.
		assertEquals(DeedLock.Outpost.ALLOWED,
			DeedLock.outpostStatus(grid, holding(LUMBRIDGE), at(KOUREND)));

		// Karamja's western tip is 7 deeds across the strait from Port Khazard.
		// An estate on that shore buys the water; it has earned the short way.
		assertEquals(DeedLock.Outpost.TOO_CLOSE,
			DeedLock.outpostStatus(grid, holding(PORT_KHAZARD), at(KARAMJA_WEST)));

		// The same tip from a Lumbridge estate is 66 deeds away, and that
		// estate has earned nothing of the sort -- so it is an outpost. The
		// rule is about the supply line, not about the water.
		assertEquals(DeedLock.Outpost.ALLOWED,
			DeedLock.outpostStatus(grid, holding(LUMBRIDGE), at(KARAMJA_WEST)));
	}
}

